using System;
using System.IO;
using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Reflection;
namespace LoopPedal {
static class SessionChecks {
 static double FilterEnergy(float position,int hz){var fx=new MasterFx{Filter=position};double sum=0;for(int i=0;i<96000;i++){float x=(float)(.2*Math.Sin(2*Math.PI*hz*i/48000)),l,r;fx.FilterOutput(x,x,out l,out r);if(i>=48000)sum+=l*l;}return sum;}
 static void CheckFilter(){var fx=new MasterFx();float l,r;fx.FilterOutput(.231f,-.117f,out l,out r);if(l!=.231f||r!=-.117f)throw new Exception("Master filter center bypass");if(FilterEnergy(-.7f,8000)>FilterEnergy(-.7f,50)*.01||FilterEnergy(.7f,100)>FilterEnergy(.7f,8000)*.01)throw new Exception("Master filter response");}
 static void CheckRouting(){for(int route=0;route<3;route++){var a=new MasterFx{Routing=route,GrainMode=2,Grain=1,GrainMix=1,Reverb=.8f,Delay=.8f,Feedback=.4f};var b=new MasterFx{Routing=route,GrainMode=2,Grain=1,GrainMix=1,Reverb=.8f,Delay=.8f,Feedback=.4f};float al,ar,bl,br;for(int i=0;i<96000;i++){float input=(float)(.12*Math.Sin(i*.029));a.Process(input,input,out al,out ar);b.Process(input,input,out bl,out br);}a.Freeze=b.Freeze=true;double energy=0,max=0;for(int i=0;i<96000;i++){float source=(float)(.15*Math.Sin(i*.083));a.Process(source,source,out al,out ar);b.Process(0,0,out bl,out br);if(i>24000){double d=source+al-bl;energy+=d*d;max=Math.Max(max,Math.Abs(d));}}if(route==0?energy<1:max>.00001)throw new Exception("FX routing/source isolation "+route);if(a.Copy().Routing!=route)throw new Exception("FX routing export copy");}}
 static void CheckMasterBypass(){for(int mode=0;mode<3;mode++)for(int route=0;route<3;route++)foreach(float mix in new[]{0f,.25f,.5f,.75f,1f}){var fx=new MasterFx{GrainMode=mode,Routing=route,Freeze=true,GrainMix=mix};foreach(float amount in new[]{0f,.25f,.5f,1f,.5f,0f}){fx.Grain=amount;float l=0,r=0;for(int i=0;i<16000;i++)fx.Process(.2f,-.1f,out l,out r);float dry=1+(Math.Min(1,2*(1-mix))-1)*amount;if(Math.Abs(.2f+l-.2f*dry)>.000002||Math.Abs(-.1f+r+.1f*dry)>.000002)throw new Exception("Proportional Grain bypass "+mode+" "+route+" "+mix+" "+amount);}}}
 static void CheckMixReset(){CheckMasterBypass();for(int mode=0;mode<3;mode++){var a=new MasterFx{Grain=1,GrainMode=mode};var b=new MasterFx{Grain=1,GrainMode=mode};float al,ar,bl,br;for(int i=0;i<96000;i++){float input=(float)(.15*Math.Sin(i*.03));a.Process(input,input,out al,out ar);b.Process(input,input,out bl,out br);}a.Freeze=b.Freeze=true;a.GrainMix=b.GrainMix=1;for(int i=0;i<12000;i++){float input=(float)(.2*Math.Sin(i*.071));a.Process(input,input,out al,out ar);b.Process(0,0,out bl,out br);if(i>8000&&Math.Abs(input+al-bl)>.000001)throw new Exception("Wet mix leaked source");}}
 var reset=new MasterFx();var defaults=new MasterFx();foreach(var f in typeof(MasterFx).GetFields()){if(f.IsStatic)continue;if(f.FieldType==typeof(float))f.SetValue(reset,.81f);else if(f.FieldType==typeof(int))f.SetValue(reset,1);else if(f.FieldType==typeof(bool))f.SetValue(reset,true);}reset.Tempo=137;reset.ResetDefaults();foreach(var f in typeof(MasterFx).GetFields())if(!f.IsStatic&&f.Name!="Tempo"&&!object.Equals(f.GetValue(reset),f.GetValue(defaults)))throw new Exception("FX reset "+f.Name);if(reset.Tempo!=137)throw new Exception("FX reset changed BPM");}
 static void CheckClouds(){uint random=123;for(int mode=1;mode<=2;mode++)foreach(float feedback in new[]{-.92f,0,.92f}){var fx=new MasterFx{GrainMode=mode,Grain=1,CloudFeedback=feedback,CloudWindow=.08f,Cloudy=.85f,GrainPitch=7};double tail=0,stereo=0;for(int i=0;i<240000;i++){random=random*1664525+1013904223;float input=i<48000?((random/4294967296f)*2-1)*.15f:0;float l,r;fx.Process(input,input,out l,out r);if(float.IsNaN(l)||float.IsInfinity(l)||Math.Abs(l)>2||Math.Abs(r)>2)throw new Exception("Cloud feedback unstable");if(i>48000&&i<144000)tail+=l*l+r*r;stereo+=Math.Abs(l-r);}if(tail<.001||stereo<.1)throw new Exception("Cloud tail/stereo missing");fx.Clear();for(int i=0;i<48000;i++){float l,r;fx.Process(0,0,out l,out r);if(l!=0||r!=0)throw new Exception("Cloud clear left tail");}if(fx.Copy().GrainMode!=mode)throw new Exception("Cloud export settings");}}
 static void CheckFx(){var fx=new MasterFx();for(int i=0;i<1000;i++){float l,r;fx.Process(.2f,.2f,out l,out r);if(l!=0||r!=0)throw new Exception("FX default bypass");}fx.Reverb=.5f;fx.Delay=.5f;fx.Time=.04f;fx.Grain=.5f;fx.GrainPitch=7;double tail=0;for(int i=0;i<144000;i++){float l,r;fx.Process(i<48000?(float)(.2*Math.Sin(i*.04)):0,i<48000?(float)(.2*Math.Sin(i*.04)):0,out l,out r);if(float.IsNaN(l)||float.IsInfinity(l)||Math.Abs(l)>20||Math.Abs(r)>20)throw new Exception("FX invalid output");if(i>48000)tail=Math.Max(tail,Math.Abs(l)+Math.Abs(r));}if(tail<.001)throw new Exception("FX tails missing");using(var a=new Engine())using(var b=new Engine()){a.Partner=b;var audio=Enumerable.Repeat(.1f,96000).ToArray();a.Layers.Add(new Layer{Original=audio,Audio=audio});a.LoopFrames=48000;a.Fx.Reverb=1;a.Fx.Delay=1;a.Fx.Grain=1;a.Fx.GrainMode=2;a.Fx.Filter=-1;b.InputMode=1;b.Sync=true;b.BPM=240;b.Begin(false);var provider=new LoopProvider(a);var bytes=new byte[4096];for(int i=0;i<94;i++)provider.Read(bytes,0,bytes.Length);b.Finish(false);var take=b.Layers.Single().Original;if(take.Skip(8192).Any(x=>Math.Abs(x-.1f)>.000001))throw new Exception("Master FX leaked into recording bus");}}
 public static void Run(){try{FxTypeChecks.Run();CheckRouting();CheckMixReset();CheckFilter();CheckClouds();
 using(var e=new Engine()){var a=Enumerable.Repeat(.1f,2000).ToArray();e.CommitLayer(new Layer{Name="A",Original=a,Audio=a});e.LoopFrames=1000;if(!e.Undo()||e.Layers.Count!=0||e.LoopFrames!=0||!e.Redo()||e.Layers.Count!=1)throw new Exception("Undo/redo recording");e.ClearLoop();if(e.Layers.Count!=0||!e.Undo()||e.Layers[0].Original[0]!=.1f||!e.Redo()||e.Layers.Count!=0)throw new Exception("Clear recovery");e.Undo();e.DeleteLayer(e.Layers[0]);if(!e.Undo()||e.Layers.Count!=1)throw new Exception("Delete recovery");e.CommitLayer(new Layer{Name="B",Original=a,Audio=a});if(e.RedoCount!=0)throw new Exception("New change retained stale redo");}
 using(var e=new Engine()){e.SetDestructive(true);for(int pass=0;pass<30;pass++){var a=Enumerable.Repeat(.01f,2000).ToArray();e.CommitLayer(new Layer{Name="Take",Original=a,Audio=a,Offset=pass*1000});if(e.Layers.Count!=1||e.LoopFrames!=1000)throw new Exception("Destructive accumulated layers");}if(Math.Abs(e.Layers[0].Original[100]-.3f)>.000001)throw new Exception("Destructive gain or accumulation");if(e.UndoCount>12||!e.Undo()||Math.Abs(e.Layers[0].Original[100]-.29f)>.000001||!e.Redo()||Math.Abs(e.Layers[0].Original[100]-.3f)>.000001)throw new Exception("Destructive history");e.ClearLoop();e.Undo();if(!e.Destructive||e.Layers.Count!=1)throw new Exception("Restore destructive clear");e.SetDestructive(false);if(e.Destructive||e.Layers.Count!=1)throw new Exception("Exit destructive");}
 using(var e=new Engine()){e.SetDestructive(true);var input=new Input(new SourceChoice{Name="Live",Left=0,Right=1});e.Inputs.Add(input);for(int pass=0;pass<2;pass++){e.Begin(false);var a=Enumerable.Repeat(.1f,2000).ToArray();input.Feed(a,a.Length,2,e.AudioFrame);e.Mix(new float[2000],1000);e.Finish(false);}if(e.Layers.Count!=1||Math.Abs(e.Layers[0].Original[500]-.2f)>.000001)throw new Exception("Recorded destructive overdub");}
 CheckFx();File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"session-tests.txt"),"PASS: Clouds/Cloud Delay stereo tails, positive/negative feedback stability, clear and copy; undo/redo; recover recent clears/deletes; new changes invalidate redo; 30 destructive overdubs keep one layer at unity sum; bounded 12-step history; destructive capture and restoration.");
 }catch(Exception e){CheckFx();File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"session-tests.txt"),"FAIL: "+e);Environment.ExitCode=1;}}
}
partial class Pedal {
 System.Collections.Generic.IEnumerable<Control> PageControls(Control root){yield return root;foreach(Control child in root.Controls)foreach(Control c in PageControls(child))yield return c;}
 public void VerifyFxTabs(){var fx=loopers[0].Fx;var levels=fxSurface.Controls.Find("MasterFxLevels",true).Single();if(!levels.Controls.OfType<Knob>().Any(k=>k.Caption=="REVERB"))throw new Exception("REVERB master label");fxMenuPad.PerformClick();Application.DoEvents();if(bankLayout.Visible||!fxSurface.Visible)throw new Exception("FX must be a separate page");var sendB=PageControls(fxSurface).OfType<Button>().Single(x=>x.Name=="FxSendBank1");var sendA=PageControls(fxSurface).OfType<Button>().Single(x=>x.Name=="FxSendBank0");levels.Controls.OfType<Knob>().Single(k=>k.Caption=="REVERB").Commit(250);sendB.PerformClick();levels.Controls.OfType<Knob>().Single(k=>k.Caption=="REVERB").Commit(750);if(fx.Reverb!=.25f||loopers[1].Fx.Reverb!=.75f)throw new Exception("A/B sends linked");ApplyMidiValue("FX.0",64);if(loopers[1].Fx.Reverb!=.75f)throw new Exception("Legacy A MIDI changed B send");sendA.PerformClick();ApplyMidiValue("FX.B.0",127);if(loopers[1].Fx.Reverb!=1||fx.Reverb==1)throw new Exception("B MIDI send depends on selected page");ApplyMidiValue("FX.B.18",127);if(loopers[1].Fx.Filter!=1||fx.Filter!=0)throw new Exception("Filter must stay with B");sendB.PerformClick();if(levels.Controls.OfType<Knob>().Single(k=>k.Caption=="FILTER").Value!=1000)throw new Exception("B filter knob value");sendA.PerformClick();if(levels.Controls.OfType<Knob>().Single(k=>k.Caption=="FILTER").Value!=500)throw new Exception("A filter knob value");loopers[1].Fx.Filter=0;loopers[1].Fx.Reverb=0;fx.Reverb=0;
 var tabs=fxSurface.Controls.Find("MasterFxTabs",true).Single();Func<int,FxTabButton> tab=id=>tabs.Controls.OfType<FxTabButton>().Single(x=>x.Effect==id);fx.GrainMode=1;tab(2).PerformClick();Application.DoEvents();if(!MidiKnobs(fxSurface).Any(k=>k.Caption=="POSITION"))throw new Exception("Fine grain position control");var freeze=PageControls(fxSurface).OfType<Button>().Single(x=>x.Name=="FreezeToggle");freeze.PerformClick();if(!fx.Freeze)throw new Exception("Front Freeze on");PageControls(fxSurface).OfType<Button>().Single(x=>x.Name=="FreezeToggle").PerformClick();if(fx.Freeze)throw new Exception("Front Freeze off");sendB.PerformClick();var freezeB=PageControls(fxSurface).OfType<Button>().Single(x=>x.Name=="FreezeToggle");freezeB.PerformClick();if(!loopers[1].Fx.Freeze||fx.Freeze||!freezeB.Text.StartsWith("B"))throw new Exception("B Freeze linked to A");sendA.PerformClick();if(!PageControls(fxSurface).OfType<Button>().Single(x=>x.Name=="FreezeToggle").Text.Contains("OFF"))throw new Exception("A Freeze readout must stay independent");fx.CopySharedSettingsTo(loopers[1].Fx);if(!loopers[1].Fx.Freeze)throw new Exception("Shared settings overwrite B Freeze");loopers[1].Fx.Freeze=false;ApplyMidiValue("FX.18",95);if(fx.Filter<.4f)throw new Exception("Master filter MIDI");ApplyMidiValue("FX.20",127);if(fx.GrainMix!=1)throw new Exception("Grain mix MIDI");var oldKnob=MidiKnobs(fxSurface).First(k=>k.Caption=="POSITION");var oldMenu=oldKnob.ContextMenuStrip;tab(0).PerformClick();if(!oldKnob.IsDisposed||!oldMenu.IsDisposed)throw new Exception("Retired FX controls leak MIDI menus");
 Action<int> doubleTab=id=>{System.Threading.Thread.Sleep(SystemInformation.DoubleClickTime+20);tab(id).PerformClick();tab(id).PerformClick();};fx.ReverbMode=0;doubleTab(0);if(fx.ReverbMode!=1||tab(0).Text!="ROOM")throw new Exception("Room type");doubleTab(0);fx.DelayMode=0;doubleTab(1);if(tab(1).Text!="Ping-Pong")throw new Exception("Ping-Pong type");doubleTab(1);if(tab(1).Text!="POTS")throw new Exception("POTS type");doubleTab(1);fx.GrainMode=0;doubleTab(2);if(fx.GrainMode!=1)throw new Exception("Clouds type");doubleTab(2);if(fx.GrainMode!=2)throw new Exception("Cloud Delay type");
 fx.Routing=1;fx.SerialOrder=0;tab(2).Reorder(0,2);Application.DoEvents();if(fx.SerialOrder!=3||tab(1).Left>=tab(0).Left||tab(0).Left>=tab(2).Left||fx.Copy().SerialOrder!=3)throw new Exception("Left-middle-right order does not match DSP/export");var drop=typeof(FxTabButton).GetMethod("OnDragDrop",BindingFlags.Instance|BindingFlags.NonPublic);PageControls(fxSurface).OfType<Button>().Single(x=>x.Name=="FxRoutingMode0").PerformClick();var data=new DataObject(new FxTabDrag{Owner=fx,Effect=1});drop.Invoke(tab(2),new object[]{new DragEventArgs(data,1,0,0,DragDropEffects.Move,DragDropEffects.Move)});if(fx.SerialOrder!=3)throw new Exception("Parallel must not reorder");PageControls(fxSurface).OfType<Button>().Single(x=>x.Name=="FxRoutingMode1").PerformClick();
 var retired=new System.Collections.Generic.List<ContextMenuStrip>();for(int i=0;i<24;i++){retired.Add(MidiKnobs(fxSurface).Last().ContextMenuStrip);tab(i%2).PerformClick();}if(retired.Any(m=>!m.IsDisposed))throw new Exception("FX editor resources accumulate");PageControls(fxSurface).OfType<Button>().Single(x=>x.Text=="FX RESET").PerformClick();if(fx.SerialOrder!=0||fx.GrainMix!=.5f||fx.Filter!=0||fx.Freeze||fx.Reverb!=0||fx.Delay!=0||fx.Grain!=0)throw new Exception("FX RESET defaults");fx.GrainMode=2;tab(2).PerformClick();Application.DoEvents();SetImmersive(true);Application.DoEvents();foreach(var control in PageControls(fxSurface)){if(control is ScrollableControl&&((ScrollableControl)control).AutoScroll)throw new Exception("FX page scrollbars");if(control is Knob&&control.Visible){var at=fxSurface.PointToClient(control.Parent.PointToScreen(control.Location));if(at.X<0||at.Y<0||at.X+control.Width>fxSurface.ClientSize.Width||at.Y+control.Height>fxSurface.ClientSize.Height)throw new Exception("FX knob outside fullscreen page: "+((Knob)control).Caption+" "+at);}}using(var image=new Bitmap(ClientSize.Width,ClientSize.Height)){DrawToBitmap(image,new Rectangle(Point.Empty,ClientSize));image.Save(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"fx-page-preview.png"));}SetImmersive(false);fxMenuPad.PerformClick();Application.DoEvents();if(!bankLayout.Visible||fxSurface.Visible)throw new Exception("FX returns to looper");if(monitorPad==null||monitorPad.Left<bankNames[0].Right||monitorPad.Right>bankClocks[0].Left)throw new Exception("Headphone placement");monitorPad.PerformClick();if(!loopers[0].InputMonitor)throw new Exception("Headphones on");monitorPad.PerformClick();if(loopers[0].InputMonitor)throw new Exception("Headphones off");}
 public void VerifySessionUi(){VerifyFxTabs();VerifyScrollAndImport();VerifyImmersive();var levels=fxSurface.Controls.Find("MasterFxLevels",true).Single();var masterKnobs=levels.Controls.OfType<Knob>().ToArray();if(masterKnobs.Length!=4||masterKnobs.Select(k=>k.Top).Distinct().Count()!=2||masterKnobs.Last().Right>levels.ClientSize.Width)throw new Exception("Master FX two-row level panel");PreviewLayers();System.Windows.Forms.Application.DoEvents();if(!recPads[0].Visible||recPads[0].Height<40||bankTracks[0].Parent.Height<100)throw new Exception("Transport/layer area clipped by compact layout");bool auto=loopers[0].AutoOverdub;DispatchMidiAction("A.AutoOverdub");if(loopers[0].AutoOverdub==auto)throw new Exception("Menu-hidden MIDI transport unavailable");DispatchMidiAction("A.AutoOverdub");int bCount=loopers[1].Layers.Count;loopers[1].Playing=true;SetSingleMode(true);if(bankPanels[1].Visible||loopers[1].Playing||bankLayout.ColumnStyles[0].Width!=100)throw new Exception("Single layout");loopers[0].SetDestructive(true);RefreshTracks();var trimmed=loopers[0].Layers[0];int untrimmed=loopers[0].LoopFrames;trimmed.TrimLength=.5;if(loopers[0].EffectiveStretch(trimmed)!=trimmed.Stretch)throw new Exception("Destructive forced stretch");Process(trimmed);var trimDeadline=DateTime.UtcNow.AddSeconds(15);while(loopers[0].LoopFrames!=untrimmed/2&&DateTime.UtcNow<trimDeadline){System.Windows.Forms.Application.DoEvents();System.Threading.Thread.Sleep(10);}if(loopers[0].LoopFrames!=untrimmed/2||trimmed.PlaybackFrames!=untrimmed/2)throw new Exception("Destructive trim cycle/playhead mismatch");trimmed.TrimLength=1;Process(trimmed);trimDeadline=DateTime.UtcNow.AddSeconds(15);while(loopers[0].LoopFrames!=untrimmed&&DateTime.UtcNow<trimDeadline){System.Windows.Forms.Application.DoEvents();System.Threading.Thread.Sleep(10);}if(loopers[0].LoopFrames!=untrimmed)throw new Exception("Destructive trim restore");if(warpChips[0].Visible)throw new Exception("Warp must hide in destructive mode");if(!bankInlineEditors[0].Visible||bankScopes[0].Visible||!bankEditPads[0].Visible)throw new Exception("Integrated destructive waveform/edit controls");if(bankTracks[0].Controls.Cast<System.Windows.Forms.Control>().SelectMany(c=>c.Controls.OfType<SampleEditor>()).Any(c=>c.Visible))throw new Exception("Duplicate destructive waveform");if(MidiKnobs(bankTracks[0]).Count()!=5)throw new Exception("Integrated destructive knobs");using(var shot=new System.Drawing.Bitmap(ClientSize.Width,ClientSize.Height)){DrawToBitmap(shot,new System.Drawing.Rectangle(System.Drawing.Point.Empty,ClientSize));shot.Save(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"inline-destructive.png"));}ToggleWarp(0);if(loopers[0].WarpLayers||loopers[0].WarpPending)throw new Exception("Destructive Warp guard");var more=Enumerable.Repeat(.01f,loopers[0].LoopFrames*2).ToArray();loopers[0].CommitLayer(new Layer{Name="Pass",Original=more,Audio=more});RefreshTracks(true);if(bankTracks[0].Controls.Count!=1)throw new Exception("Stale destructive layer cards remain");if(!singleMode||loopers[0].Layers.Count!=1||!loopers[0].Destructive)throw new Exception("Combined single/destructive");loopers[0].ClearLoop();RestoreHistory(0,false);if(loopers[0].Layers.Count!=1)throw new Exception("UI clear recovery");RestoreHistory(0,true);if(loopers[0].Layers.Count!=0)throw new Exception("UI redo clear");SetSingleMode(false);if(!bankPanels[1].Visible||loopers[1].Layers.Count!=bCount||loopers[1].Playing)throw new Exception("Dual restore changed B");}
